	DEFINE_PROTO_STRUCT(cov_layout, j_vec ^ i_vec);
	// mean: j      (M)
	DEFINE_PROTO_STRUCT(mean_layout, j_vec);
} tuning;

// initialization function
void init_array(num_t &float_n, auto data) {
	// data: k x j  (k ~ N, j ~ M)
	using namespace noarr;

	// float_n = N (number of samples)
	float_n = (num_t)(data | get_length<'k'>());

	auto m_len = data | get_length<'j'>();
	const num_t inv_m_len = num_t(1.0) / num_t(m_len);

	// Traverse row-by-row: for each sample k, walk contiguous features j
	traverser(data).template for_dims<'k'>([&](auto tk) {
		tk.for_each([&](auto state) {
			auto [k, j] = get_indices<'k', 'j'>(state);
			// Use a precomputed reciprocal to avoid a division in the inner loop
			data[state] = (num_t(k) * num_t(j)) * inv_m_len;
		});
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_covariance(num_t float_n, auto data, auto cov, auto mean) {
	// data: k x j  (N samples, M features)
	// cov:  i x j  (M x M)
	// mean: j      (M)
	using namespace noarr;

	// view of data where the feature dimension is called 'i'
	// (for cov's row index); data_i: k x i
	auto data_i = data ^ noarr::rename<'j', 'i'>();

#pragma scop
	// -------------------------------------------------------------------------
	// 1) Compute column means:
	//    mean[j] = (1/n) * sum_k data[k][j]
	//
	// Optimized for data locality:
	//  - First zero mean[j].
	//  - Then, for each sample k, add the whole row data[k][*] into mean[*].
	// This walks data row-by-row (k fixed, j varying), which is contiguous in
	// memory for the chosen layout (j is the inner dimension).
	// -------------------------------------------------------------------------

	// Initialize mean[j] = 0
	traverser(mean).for_each([&](auto sj) {
		mean[sj] = num_t(0);
	});

	// Accumulate sums: for each sample k, accumulate all features j
	traverser(data, mean).template for_dims<'k'>([&](auto tk) {
		// tk has 'k' fixed; for_each iterates remaining dim 'j'
		tk.for_each([&](auto s) {
			// s contains ('k','j'); mean ignores 'k' and uses 'j' only
			mean[s] += data[s];
		});
	});

	// Scale by 1/n to obtain the mean
	const num_t inv_n = num_t(1.0) / float_n;
	traverser(mean).for_each([&](auto sj) {
		mean[sj] *= inv_n;
	});

	// -------------------------------------------------------------------------
	// 2) Center the data:
	//      data[k][j] -= mean[j]
	//
	// Again traverse row-by-row (k outer, j inner) to keep accesses contiguous.
	// -------------------------------------------------------------------------
	traverser(data, mean).template for_dims<'k'>([&](auto tk) {
		tk.for_each([&](auto s) {
			data[s] -= mean[s]; // mean[s] uses only 'j' from the state
		});
	});

	// -------------------------------------------------------------------------
	// 3) Covariance:
	//      cov[i][j] = sum_k data[k][i] * data[k][j] / (float_n - 1)
	//      cov[j][i] = cov[i][j]
	//
	// We traverse i and j explicitly and, for each (i,j) with j >= i, accumulate
	// over k. To reduce memory traffic on cov, we:
	//   - accumulate into a local variable `sum` kept in registers,
	//   - write cov[i][j] only once per (i,j),
	//   - then mirror to cov[j][i].
	// The normalization factor 1/(n-1) is also precomputed once.
	// -------------------------------------------------------------------------
	const num_t inv_nm1 = num_t(1.0) / (float_n - num_t(1.0));

	traverser(cov, data, data_i).template for_dims<'i'>([&](auto ti) {
		ti.template for_dims<'j'>([&](auto tij) {
			// State with fixed i,j (k is not present here)
			auto s_ij = tij.state();
			auto [i_idx, j_idx] = get_indices<'i', 'j'>(s_ij);

			// Only compute upper triangle (including diagonal)
			if (j_idx < i_idx)
				return;

			num_t sum = num_t(0);

			// For fixed (i,j), iterate over samples k and accumulate
			tij.for_each([&](auto sk) {
				// sk contains ('k','i','j'):
				//  - data[sk]   uses 'k' and 'j'
				//  - data_i[sk] uses 'k' and 'i'
				sum += data[sk] * data_i[sk];
			});

			const num_t value = sum * inv_nm1;

			// Write cov[i][j]
			cov[s_ij] = value;

			// Symmetry: cov[j][i] = cov[i][j]
			auto s_ji = noarr::idx<'i', 'j'>(j_idx, i_idx);
			cov[s_ji] = value;
		});
	});
#pragma endscop
}

} // namespace

