	// data: k x j  (N samples, M features)
	// cov:  i x j  (M x M)
	// mean: j      (M)
	using namespace noarr;

	// view of data where the feature dimension is called 'i'
	// (for cov's row index); data_i: k x i
	auto data_i = data ^ noarr::rename<'j', 'i'>();

	// Precompute normalization factors to avoid repeated divisions
	const num_t inv_float_n       = num_t(1) / float_n;
	const num_t inv_float_n_minus = num_t(1) / (float_n - num_t(1));

	// Cache M (= length in feature dimension) for later use
	const std::size_t m_len = cov | get_length<'i'>();

#pragma scop
	// --------------------------------------------------------------------
	// 1) mean[j] = (1/n) * sum_k data[k][j]
	// --------------------------------------------------------------------

