	// 3) Covariance matrix:
	//    for i in 0..M-1
	//      for j in i..M-1
	//        cov[i][j] = sum_k data[k][i] * data[k][j] / (float_n - 1)
	//        cov[j][i] = cov[i][j]
	// --------------------------------------------------------------------
