			});

			// Normalize and write symmetric entries
			const num_t cval = acc * inv_float_n_minus;

			cov[s_ij] = cval;

			// Mirror to (j, i) unless we are on the diagonal
			const std::size_t j_idx = get_index<'j'>(s_ij);
			if (j_idx != i_idx) {
