	auto m_len = data | get_length<'j'>();

	// Initialize in row-major order: outer 'k' (samples), inner 'j' (features)
	traverser(data).template for_dims<'k'>([=](auto tk) {
		tk.template for_each<'j'>([=](auto state) {
			auto [k, j] = get_indices<'k', 'j'>(state);
			data[state] = (num_t)(k * j) / (num_t)m_len;
		});
	});
}

// computation kernel
// NOTE: The boilerplate (signature, pragmas, etc.) is preserved as requested.
[[gnu::flatten, gnu::noinline]]
void kernel_covariance(num_t float_n, auto data, auto cov, auto mean) {
	// data: k x j  (N samples, M features), row-major in 'j'
	// cov:  i x j  (M x M), row-major in 'j'
	// mean: j      (M)
	using namespace noarr;

	// view of data where the feature dimension is called 'i'
	// (for cov's row index); data_i: k x i
	auto data_i = data ^ noarr::rename<'j', 'i'>();

	// length in feature / cov-column dimension
	const std::size_t m_len = cov | get_length<'j'>();
	const num_t inv_float_n = (num_t)1.0 / float_n;
	const num_t inv_float_n_minus_1 = (num_t)1.0 / (float_n - (num_t)1.0);

#pragma scop
	// --------------------------------------------------------------------
	// 1) mean[j] = (1/n) * sum_k data[k][j]
	//    We compute the mean in k-major (row-major) order to match
	//    the row-major layout of 'data' (j is the inner/fast dimension).
	// --------------------------------------------------------------------

	// 1a) initialize mean[j] = 0
	traverser(mean).for_each([&](auto s) {
		mean[s] = (num_t)0;
	});

	// 1b) accumulate sums over k and j (row-major traversal of 'data')
	traverser(data, mean).template for_dims<'k'>([&](auto tk) {
		tk.template for_each<'j'>([&](auto s) {
			// s has indices {k, j}; 'mean' ignores 'k' and uses 'j'
			mean[s] += data[s];
		});
	});

	// 1c) divide by n
	traverser(mean).for_each([&](auto s) {
		mean[s] *= inv_float_n;
	});

	// --------------------------------------------------------------------
	// 2) data[k][j] -= mean[j]
	//    Also done in row-major order for better locality.
	// --------------------------------------------------------------------
	traverser(data, mean).template for_dims<'k'>([&](auto tk) {
		tk.template for_each<'j'>([&](auto s) {
			data[s] -= mean[s];
		});
	});

	// --------------------------------------------------------------------
	// 3) covariance
	//
	//    We switch to a "sample-major" formulation:
	//
	//      cov[i][j] = sum_k data[k][i] * data[k][j]  for j >= i
	//
	//    i.e. for each centered sample (row k), we form its contribution
	//    to the upper-triangular part of the covariance matrix.
	//
	//    This improves data locality significantly:
	//      - each sample row of 'data' is walked contiguously in 'j'
	//      - we avoid scanning 'data' in the strided 'k'-direction
	// --------------------------------------------------------------------

	// 3a) clear covariance matrix
	traverser(cov).for_each([&](auto s) {
		cov[s] = (num_t)0;
	});

	// 3b) accumulate outer products of centered samples
	traverser(cov, data, data_i).template for_dims<'k'>([&](auto tk) {
		// 'tk' has current sample index 'k' fixed; remaining dims are 'i', 'j'
		tk.template for_dims<'i'>([&](auto ti) {
			// 'ti' has 'k' and 'i' fixed; remaining dim is 'j'
			auto s_ki = ti.state();
			const std::size_t i_idx = get_index<'i'>(s_ki);

			// x_i = data[k][i]; fetched once per (k, i) and reused across j
			const num_t x_i = data_i[s_ki];

			// Iterate only over j >= i using a slice on the 'j' dimension.
			// The length m_len - i_idx is always >= 1 here.
			ti.order(noarr::slice<'j'>(i_idx, m_len - i_idx))
			  .for_each([&](auto s_kij) {
				  // s_kij has indices {k, i, j}
				  // cov is indexed by {i, j}; extra 'k' is ignored.
				  cov[s_kij] += x_i * data[s_kij]; // data[k][j]
			  });
		});
	});

	// 3c) normalize by (n-1) and enforce symmetry: cov[j][i] = cov[i][j]
	//
	// We traverse only the upper triangle (j >= i) to avoid redundant work.
	traverser(cov).template for_dims<'i'>([&](auto ti) {
		auto s_i = ti.state();
		const std::size_t i_idx = get_index<'i'>(s_i);

		ti.order(noarr::slice<'j'>(i_idx, m_len - i_idx))
		  .for_each([&](auto s_ij) {
			  const std::size_t j_idx = get_index<'j'>(s_ij);

			  // scale cov[i][j]
			  cov[s_ij] *= inv_float_n_minus_1;

			  // write symmetric counterpart when off-diagonal
			  if (j_idx != i_idx) {
				  auto s_ji = noarr::idx<'i', 'j'>(j_idx, i_idx);
				  cov[s_ji] = cov[s_ij];
			  }
		  });
	});
#pragma endscop
}

