	traverser(data).template for_dims<'k'>([&](auto tk) {
		tk.template for_each<'j'>([&](auto state) {
			auto [k, j] = get_indices<'k', 'j'>(state);
			data[state] = (num_t)(k * j) / (num_t)m_len;
		});
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_covariance(num_t float_n, auto data, auto cov, auto mean) {
	// data: k x j  (N samples, M features)
	// cov:  i x j  (M x M)
	// mean: j      (M)
	using namespace noarr;

	// View of data where the feature dimension is called 'i'
	// (for cov's row index); data_i: k x i
	auto data_i = data ^ noarr::rename<'j', 'i'>();

#pragma scop
	// ------------------------------------------------------------------
	// 1) Compute mean of each feature:
	//      mean[j] = (1 / N) * sum_k data[k][j]
	//
	// We traverse samples k outer and features j inner, which streams
	// each sample row of `data` in memory-contiguous order (j is inner).
	// ------------------------------------------------------------------

	// 1a) Initialize means to zero
	traverser(mean).for_each([&](auto sj) {
		mean[sj] = (num_t)0;
	});

	// 1b) Accumulate sums over all samples
	traverser(data, mean).template for_dims<'k'>([&](auto tk) {
		// For a fixed sample k, iterate all features j (contiguous)
		tk.template for_each<'j'>([&](auto state) {
			// `state` carries both k and j; `mean` ignores k
			mean[state] += data[state];
		});
	});

	// 1c) Normalize by the number of samples
	traverser(mean).for_each([&](auto sj) {
		mean[sj] /= float_n;
	});


	// ------------------------------------------------------------------
	// 2) Center the data:
	//      data[k][j] -= mean[j]
	//
	// Again, use k as outer and j as inner to walk rows contiguously.
	// ------------------------------------------------------------------
	traverser(data, mean).template for_dims<'k'>([&](auto tk) {
		tk.template for_each<'j'>([&](auto state) {
			data[state] -= mean[state];
		});
	});


	// ------------------------------------------------------------------
	// 3) Compute covariance matrix:
	//
	//     cov[i][j] = sum_k data[k][i] * data[k][j] / (float_n - 1)
	//     cov[j][i] = cov[i][j]
	//
	// We reorganize the loops as:
	//
	//   for k in samples
	//     for i in features
	//       xi = data[k][i]
	//       for j in features, j >= i
	//         cov[i][j] += xi * data[k][j]
	//
	// This has the same arithmetic complexity as the original
	// i-j-k ordering but:
	//   * streams each centered sample row once (k outer, j inner),
	//   * reuses xi across all j >= i for that sample,
	//   * touches each cov[i][j] once per sample.
	//
	// We first zero the covariance matrix, then accumulate, then
	// normalize and symmetrize.
	// ------------------------------------------------------------------

	// 3a) Initialize covariance to zero
	traverser(cov).for_each([&](auto s) {
		cov[s] = (num_t)0;
	});

	// 3b) Accumulate the upper triangle via outer products of centered samples
	traverser(cov, data, data_i).template for_dims<'k'>([&](auto tk) {
		// For each sample k
		tk.template for_dims<'i'>([&](auto tki) {
			// Fixed (k, i); obtain data[k][i] once and reuse for all j >= i
			auto s_ki = tki.state(); // has 'k' and 'i'
			const num_t x_i = data_i[s_ki];

			// Iterate all j; we guard with j_idx < i_idx to stay in upper triangle
			tki.template for_dims<'j'>([&](auto tkij) {
				auto s_kij = tkij.state(); // has 'k', 'i', 'j'
				auto [i_idx, j_idx] = get_indices<'i', 'j'>(s_kij);

				// Only compute upper triangle (including diagonal)
				if (j_idx < i_idx)
					return;

				// `data` uses (k, j); extra 'i' is ignored.
				// `cov` uses (i, j); extra 'k' is ignored.
				cov[s_kij] += x_i * data[s_kij];
			});
		});
	});

	// 3c) Normalize by (N - 1) and enforce symmetry cov[j][i] = cov[i][j]
	const num_t norm = (num_t)1.0 / (float_n - (num_t)1.0);

	traverser(cov).template for_dims<'i'>([&](auto ti) {
		ti.template for_dims<'j'>([&](auto tij) {
			auto s_ij = tij.state();
			auto [i_idx, j_idx] = get_indices<'i', 'j'>(s_ij);

			// Only process the upper triangle; mirror into lower.
			if (j_idx < i_idx)
				return;

			// Scale the accumulated sum
			cov[s_ij] *= norm;

			// Mirror to the symmetric position
			auto s_ji = noarr::idx<'i', 'j'>(j_idx, i_idx);
			cov[s_ji] = cov[s_ij];
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t m = M;

	// input data
	num_t float_n;

	// set lengths for all relevant dimensions
	auto set_lengths =
		noarr::set_length<'k'>(n) ^ // samples
		noarr::set_length<'i'>(m) ^ // cov rows
		noarr::set_length<'j'>(m);  // features / cov cols

	// allocate bags
	auto data = noarr::bag(noarr::scalar<num_t>() ^ tuning.data_layout ^ set_lengths);
	auto cov  = noarr::bag(noarr::scalar<num_t>() ^ tuning.cov_layout  ^ set_lengths);
	auto mean = noarr::bag(noarr::scalar<num_t>() ^ tuning.mean_layout ^ set_lengths);

	// initialize data
	init_array(float_n, data.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_covariance(float_n, data.get_ref(), cov.get_ref(), mean.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results to stderr (to prevent DCE in benchmarking harnesses)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, cov.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing to stdout
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
